/*
 * prog44_miller_rabin – reconstructed from the supplied binary.
 *
 * Behaviour (stdout):
 *   NO_INPUT      – when the program is invoked without a numeric argument.
 *   BAD_INPUT     – when the argument cannot be parsed as a complete decimal integer.
 *   OUT_OF_RANGE  – when the parsed value is larger than 0xBFA17DC6.
 *   PRIME         – when the value is a prime number (deterministic Miller‑Rabin).
 *   NOT_PRIME     – for all other numeric values (including 0, 1 and negative numbers).
 *
 * The original binary used a deterministic Miller‑Rabin test with the bases
 * 2, 3, 5, 7, 11 and 13, and it rejected inputs larger than 0xBFA17DC6.
 * The implementation below follows the same logic, but in clean, readable C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

/* ---------- modular arithmetic (uses 128‑bit intermediate) ---------- */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    __uint128_t t = ( __uint128_t ) a * b;
    return (uint64_t)(t % mod);
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t res = 1;
    while (exp) {
        if (exp & 1)
            res = mul_mod(res, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return res;
}

/* ---------- deterministic Miller‑Rabin for 64‑bit numbers ---------- */
static int is_prime_uint64(uint64_t n)
{
    /* Small numbers and even numbers */
    if (n < 2)               return 0;
    if (n == 2 || n == 3)    return 1;
    if ((n & 1ULL) == 0ULL)  return 0;

    /* Write n‑1 as d·2^s with d odd */
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1ULL) == 0ULL) {
        d >>= 1;
        ++s;
    }

    /* Deterministic bases for n ≤ 0xBFA17DC6 (the limit used by the binary) */
    const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a % n == 0)               /* a is a multiple of n → treat as passed */
            continue;

        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;

        int passed = 0;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                passed = 1;
                break;
            }
        }
        if (!passed)
            return 0;                 /* composite */
    }
    return 1;                         /* probably prime → deterministic for this range */
}

/* ------------------------------- main ------------------------------- */
int main(int argc, char **argv)
{
    /* 1. No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Parse the argument as a signed decimal integer */
    char *endptr = NULL;
    long long signed_val = strtoll(argv[1], &endptr, 10);

    /* 3. Ensure the whole string was consumed */
    if (endptr == NULL || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* 4. Reject values outside the allowed range */
    const uint64_t MAX_VAL = 0xBFA17DC6ULL;
    if ((unsigned long long)signed_val > MAX_VAL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 5. Perform the primality test (treat negative numbers as non‑prime) */
    uint64_t n = (uint64_t)signed_val;
    if (is_prime_uint64(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
